{
  "up": "Select molecule_chembl_id AS compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism From molecule_dictionary MD Join activities ACT ON MD.molregno = ACT.molregno Join assays AS ON ACT.assay_id = AS.assay_id Join target_dictionary TD ON AS.tid = TD.tid Join compound_structures CS ON MD.molregno = CS.molregno Join docs D ON ACT.doc_id = D.doc_id Join compound_records CR ON ACT.record_id = CR.record_id Join pubmed_or_doi PD ON D.pubmed_id = PD.pubmed_id OR D.doi = PD.doi Where MD.pref_name = 'C‑C chemokine receptor type 2' And AS.assay_organism = 'Homo sapiens' And ACT.standard_type = 'IC50' And ACT.standard_relation = '=' And ACT.standard_value IS NOT NULL And ACT.standard_units = 'nM' And ACT.pubmed_id IS NOT NULL Or D.doi IS NOT NULL Order By compound_chembl_id, canonical_smiles, compound_key, pubmed_id_or_doi, assay_description, standard_type, standard_relation, standard_value, standard_units, activity_comment, target_chembl_id, target_name, target_organism"
}
